package dec.core.context.runtime;
import java.util.Objects;
/** P2 大小写敏感的 opaque runtime ID；值本身不携带任何 authority。 */
public final class RuntimeObjectId implements Comparable<RuntimeObjectId>{private final String value;private RuntimeObjectId(String value){this.value=requireValue(value);}public static RuntimeObjectId of(String value){return new RuntimeObjectId(value);}public String value(){return value;}@Override public int compareTo(RuntimeObjectId other){return value.compareTo(Objects.requireNonNull(other,"other").value);}@Override public boolean equals(Object other){return this==other||other instanceof RuntimeObjectId&&value.equals(((RuntimeObjectId)other).value);}@Override public int hashCode(){return value.hashCode();}@Override public String toString(){return value;}private static String requireValue(String raw){Objects.requireNonNull(raw,"value");if(raw.trim().isEmpty()||!raw.equals(raw.trim()))throw new IllegalArgumentException("value must be non-blank and trimmed");return raw;}}
